const api=OwaysAPI.request,E=OwaysAPI.escape,$=s=>document.querySelector(s);function status(m){$('#status').textContent=m}async function run(fn){try{await fn()}catch(e){status(e.message)}}async function refresh(){const [c,s,o]=await Promise.all([api('/api/admin/categories'),api('/api/admin/services'),api('/api/admin/orders')]);$('#category-select').innerHTML=c.categories.map(c=>`<option value="${E(c.id)}">${E(c.name)}</option>`).join('');$('#categories').innerHTML=c.categories.map(c=>`<p>${E(c.name)}</p>`).join('');$('#services').innerHTML=s.services.map(s=>`<article class="portal-row"><div><b>${E(s.name)}</b><small>${E(s.category_name)} · ${E(s.status)}</small></div><a class="button outline" href="/account?service=${encodeURIComponent(s.slug)}">معاينة الطلب</a></article>`).join('');$('#orders').innerHTML=o.orders.length?o.orders.map(o=>`<article class="portal-row"><div><b>${E(o.public_reference)}</b><small>${E(o.full_name)} · ${E(o.phone)}</small><small>${E(o.fulfillment_status)} · ${E(o.payment_status)}</small></div><button class="button outline" data-order="${E(o.id)}">مراجعة الطلب</button></article>`).join(''):'<p>لا توجد طلبات.</p>'}
$('#category-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/admin/categories',Object.fromEntries(new FormData(e.target)));e.target.reset();await refresh();status('تم حفظ التصنيف.')})};$('#add-requirement').onclick=()=>{const row=document.createElement('div');row.className='requirement-row';row.innerHTML='<label>معرّف الحقل<input data-key required pattern="[a-z][a-z0-9_]*" dir="ltr"></label><label>اسم الحقل<input data-label required></label><label>النوع<select data-type><option value="text">نص</option><option value="email">بريد إلكتروني</option><option value="phone">هاتف</option><option value="url">رابط</option><option value="number">رقم</option><option value="textarea">نص طويل</option><option value="select">اختيار</option></select></label><label>شرح الإدخال<input data-help></label><label>خيارات الاختيار، خيار في كل سطر<textarea data-options></textarea></label><label><input type="checkbox" data-required checked>مطلوب</label><button type="button" class="button outline" data-remove-field>حذف الحقل</button>';$('#requirements').append(row)};$('#service-form').onsubmit=e=>{e.preventDefault();run(async()=>{const b=Object.fromEntries(new FormData(e.target));b.features=b.features.split('\n').map(x=>x.trim()).filter(Boolean);b.instructions={before_order:b.before_order,during_activation:b.during_activation,after_completion:b.after_completion};b.requirements=[...document.querySelectorAll('.requirement-row')].map(r=>({field_key:r.querySelector('[data-key]').value,label:r.querySelector('[data-label]').value,input_type:r.querySelector('[data-type]').value,required:r.querySelector('[data-required]').checked,help_text:r.querySelector('[data-help]').value,options:r.querySelector('[data-options]').value.split('\n').map(x=>x.trim()).filter(Boolean)}));await api('/api/admin/services',b);e.target.reset();$('#requirements').innerHTML='';await refresh();status('تم حفظ الخدمة وباقتها.')})};document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){$('#orders-tab').hidden=tab.dataset.tab!=='orders';$('#catalog-tab').hidden=tab.dataset.tab!=='catalog'}const remove=e.target.closest('[data-remove-field]');if(remove)remove.closest('.requirement-row').remove();const order=e.target.closest('[data-order]');if(order)run(async()=>{const o=await api('/api/admin/orders/'+order.dataset.order);$('#order-detail').hidden=false;$('#order-detail').innerHTML=`<h2>${E(o.public_reference)}</h2><p>${E(o.full_name)} · ${E(o.phone)}</p>${o.items.map(i=>`<h3>${E(i.package_snapshot.service_name)} — ${E(i.package_snapshot.name)}</h3>${i.answers.map(a=>`<p>${E(a.field_key)}: ${E(a.value_json)}</p>`).join('')}`).join('')}<form id="update-order"><label>الحالة<select name="status"><option value="review">قيد المراجعة</option><option value="awaiting_customer">بانتظار إجراء من العميل</option><option value="ready">جاهز للتنفيذ</option><option value="processing">قيد التنفيذ</option><option value="cancelled">ملغي</option></select></label><label>رسالة ظاهرة للعميل<textarea name="note"></textarea></label><button class="button">حفظ التحديث</button></form><p class="fine">التنفيذ يتطلب دفعًا مؤكدًا. إدارة الدفع وإكمال التفعيل لم تُفعّل في هذا الإصدار.</p>`;$('#update-order').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/admin/orders/'+o.id,Object.fromEntries(new FormData(e.target)));await refresh();status('تم تحديث الطلب.')})}})});run(async()=>{const u=(await api('/api/auth/me')).user;if(u.role!=='admin')throw Error('هذه الصفحة للأدمن فقط.');$('#admin-content').hidden=false;await refresh()});
